import{_ as t,o as a,c as g,a3 as o}from"./chunks/framework.DX_KL3e0.js";const m=JSON.parse('{"title":"Bù công · Tăng ca · Công tác / WFH","description":"","frontmatter":{},"headers":[],"relativePath":"huong-dan/bu-cong-tang-ca.md","filePath":"huong-dan/bu-cong-tang-ca.md","lastUpdated":1783009205000}'),c={name:"huong-dan/bu-cong-tang-ca.md"};function h(r,n,i,e,s,u){return a(),g("div",null,[...n[0]||(n[0]=[o('<h1 id="bu-cong-·-tang-ca-·-cong-tac-wfh" tabindex="-1">Bù công · Tăng ca · Công tác / WFH <a class="header-anchor" href="#bu-cong-·-tang-ca-·-cong-tac-wfh" aria-label="Permalink to &quot;Bù công · Tăng ca · Công tác / WFH&quot;">​</a></h1><blockquote><p><strong>🎯 Mục tiêu:</strong> Khai báo cho ngày quên chấm, đi công tác, làm tại nhà, làm theo ca, hoặc tăng ca. <strong>👤 Ai làm được:</strong> Mọi nhân sự. · <strong>⏱️ Khoảng:</strong> ~1 phút. · Có hiệu lực <strong>sau khi quản lý duyệt</strong>.</p></blockquote><p>Tất cả thao tác ngay trong <strong>bảng công tháng</strong>: vào <strong>Dữ Liệu Chấm Công → Tra Cứu Dữ Liệu Công</strong>, tìm đúng ngày cần khai.</p><h2 id="bu-cong-quen-thieu-cham-·-cong-tac-·-wfh-·-lam-theo-ca" tabindex="-1">Bù công (quên/thiếu chấm · công tác · WFH · làm theo ca) <a class="header-anchor" href="#bu-cong-quen-thieu-cham-·-cong-tac-·-wfh-·-lam-theo-ca" aria-label="Permalink to &quot;Bù công (quên/thiếu chấm · công tác · WFH · làm theo ca)&quot;">​</a></h2><ol><li>Bấm <strong>Bù Công</strong> trên ngày cần khai.</li><li>Chọn <strong>chế độ</strong>: <ul><li><strong>Bù công (chấm thiếu giờ)</strong> — nhập <strong>giờ vào</strong> &amp; <strong>giờ ra</strong>.</li><li><strong>Công tác</strong> / <strong>Làm việc tại nhà (WFH)</strong> / <strong>Làm theo ca</strong> — tự tính <strong>1 ngày công đầy đủ</strong>, không cần nhập giờ.</li></ul></li><li>Nhập <strong>lý do</strong> → bấm <strong>Gửi Yêu Cầu</strong>.</li></ol><h2 id="tang-ca" tabindex="-1">Tăng ca <a class="header-anchor" href="#tang-ca" aria-label="Permalink to &quot;Tăng ca&quot;">​</a></h2><ol><li>Bấm nút <strong>tăng ca</strong> trên ngày tương ứng.</li><li>Chọn <strong>giờ bắt đầu</strong> &amp; <strong>giờ kết thúc</strong> — hệ thống tự tính theo khung: <ul><li>🌆 <strong>Khung tối:</strong> 17:30 – 22:00</li><li>🌙 <strong>Khung đêm:</strong> 22:00 – 07:00 (qua đêm hiện nhãn &quot;+1 ngày&quot;)</li></ul></li><li>Nhập lý do (tùy chọn) → bấm <strong>Gửi Khai Báo</strong>.</li></ol><h2 id="✅-ket-qua" tabindex="-1">✅ Kết quả <a class="header-anchor" href="#✅-ket-qua" aria-label="Permalink to &quot;✅ Kết quả&quot;">​</a></h2><p>Yêu cầu gửi tới quản lý. Sau khi <strong>duyệt</strong> (tại <a href="/help/huong-dan/duyet-yeu-cau.html">Duyệt yêu cầu → Duyệt Công</a>), dữ liệu công của bạn <strong>tự cập nhật</strong>.</p><h2 id="💡-meo" tabindex="-1">💡 Mẹo <a class="header-anchor" href="#💡-meo" aria-label="Permalink to &quot;💡 Mẹo&quot;">​</a></h2><p>Làm các khai báo này <strong>trước thời gian bảng công tự gửi</strong> của công ty — sau khi bảng công được gửi, số liệu đã chốt. Xem <a href="/help/huong-dan/nop-bang-cong.html">Bảng công cuối kỳ</a>.</p><p><em>Chi tiết: <a href="/help/chuc-nang/cham-cong.html#_3-bu-cong-va-tang-ca">Bù công và tăng ca</a></em></p>',12)])])}const d=t(c,[["render",h]]);export{m as __pageData,d as default};
